[platformio]
default_envs = ota
extra_configs = secrets.ini  ; Mat khau OTA, copy tu secrets.example.ini

[env:esp32cam]
platform = espressif32
board = esp32cam
framework = arduino
monitor_speed = 115200
monitor_rts = 0
monitor_dtr = 0
monitor_filters = esp32_exception_decoder
; 2 vung app 1.9MB de nap qua WiFi (huge_app.csv chi co 1 vung nen khong OTA duoc)
board_build.partitions = min_spiffs.csv
build_flags = '-DOTA_PASSWORD="${ota.password}"'

[env:ota]
extends = env:esp32cam
upload_protocol = espota
upload_port = esp32cam.local  ; Neu laptop khong tim thay ten nay thi thay bang IP, vd 192.168.100.102
upload_flags = --auth=${ota.password}
