403:  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t) { staAssocTime = millis(); }, ARDUINO_EVENT_WIFI_STA_CONNECTED);
404:  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t) { staAssocTime = 0; }, ARDUINO_EVENT_WIFI_STA_GOT_IP);
405:  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t info) {
407:    // Bo qua ASSOC_LEAVE: do chinh checkWifi() goi WiFi.disconnect() truoc moi lan thu lai
412:  if (WiFi.softAP(AP_SSID, AP_PASSWORD)) {
413:    Serial.printf("Phat WiFi \"%s\"  ->  http://%s/capture\n", AP_SSID, WiFi.softAPIP().toString().c_str());
423:  if (WiFi.status() == WL_CONNECTED) {
427:                    WiFi.localIP().toString().c_str(), HOSTNAME);
438:  if (WiFi.softAPgetStationNum() > 0) {
449:      WiFi.disconnect();
466:    WiFi.disconnect();
472:  Serial.begin(115200);
474:  pinMode(FLASH_LED_PIN, OUTPUT);
475:  digitalWrite(FLASH_LED_PIN, LOW);
477:  Serial2.begin(9600, SERIAL_8N1, NANO_RX_PIN, NANO_TX_PIN);
498:  if (MDNS.begin(HOSTNAME)) {
499:    MDNS.addService("http", "tcp", 80);
503:  // mDNS da bat o tren nen tat phan mDNS cua ArduinoOTA
504:  ArduinoOTA.setHostname(HOSTNAME);
505:  ArduinoOTA.setPassword(OTA_PASSWORD);
506:  ArduinoOTA.setMdnsEnabled(false);
507:  ArduinoOTA.onStart([]() { Serial.println("Dang nhan code moi qua WiFi..."); });
508:  ArduinoOTA.onEnd([]() { Serial.println("Nap xong, khoi dong lai"); });
509:  ArduinoOTA.onError([](ota_error_t err) { Serial.printf("Nap qua WiFi loi %u\n", err); });
510:  ArduinoOTA.begin();
512:  server.on("/", handleRoot);
513:  server.on("/capture", handleCapture);
514:  server.on("/status", handleStatus);
515:  server.on("/result", HTTP_POST, handleResult);

