11	[env:nanoatmega328]
12	platform = atmelavr
13	board = nanoatmega328new
14	framework = arduino
15	monitor_speed = 9600
16	lib_deps = 
17	    arduino-libraries/LiquidCrystal @ ^1.0.7----
18	#include <Arduino.h>
19	#include <LiquidCrystal.h>
20	#include <SoftwareSerial.h>
21	
22	// Khoi tao LCD 1602 theo cac chan:
23	// LiquidCrystal(RS, Enable, D4, D5, D6, D7)
24	// Khoi tao LCD 1602 theo cac chan da hoat dong tot
25	LiquidCrystal lcd(12, 11, 5, 4, 3, 2);
26	
27	// Cong Serial thu 2 noi sang ESP32-CAM qua module BSS138:
28	// D8 nhan (tu ESP IO13, kenh HV2-LV2), D9 gui (sang ESP IO14, kenh HV1-LV1)
29	SoftwareSerial espSerial(8, 9);
30	
31	const int SOIL_PIN = A0; // Chan doc Analog cua cam bien do am dat
32	const int RELAY_PIN = 7; // Chan dieu khien relay may bom (IN cua module relay)
33	
34	// Module relay 5V pho bien kich muc LOW (IN = LOW thi relay dong).
35	// Neu relay cua ban kich muc HIGH thi doi thanh HIGH.
36	const int RELAY_ACTIVE = LOW;
37	
38	const int MIST_PIN = 6;             // Chan dieu khien relay may phun suong 5V (IN2 neu dung module relay 2 kenh)
39	const int MIST_RELAY_ACTIVE = LOW;  // Kich muc LOW giong relay bom
40	
41	// Mach phun JY-M36A0 khong nho trang thai: moi lan duoc cap dien no o trang thai TAT, phai bam nut S1 1 lan moi phun.
42	// D10 noi qua diode 1N4007 (vach ve phia Nano) toi chan tin hieu cua S1. Keo D10 xuong LOW = bam S1;
43	// luc thuong D10 tha noi (INPUT), diode chan nen Nano khong bao gio day dien vao mach phun.
44	const int MIST_BTN_PIN = 10;
45	const unsigned long MIST_BOOT_MS = 500;   // Relay cap dien xong doi mach phun khoi dong roi moi bam
46	const unsigned long MIST_PRESS_MS = 200;  // Giu nut 0,2 giay
47	
48	// Phun suong theo gio that (ESP32-CAM gui xuong) va che do ESP gui theo tinh trang la AI bao.
49	// Chi phun ban ngay de la kip kho truoc toi: la uot qua dem lam benh nam, vi khuan lan nhanh.
50	// Nhip phun tinh theo dong ho nen luon phun dung luc :00, :30 (hoac :00, :15, :30, :45).
51	const int MIST_NORMAL = 1;                   // La khoe, benh virus, hoac chua co ket qua AI
52	const int MIST_STOP = 2;                     // La benh nam / vi khuan, hoac nghi benh: khong phun
53	const int MIST_BOOST = 3;                    // Chac chan nhen do (so am): phun day hon
54	const long MIST_ON_SEC = 30;                 // Moi lan phun 30 giay...
55	const long MIST_EVERY_SEC = 30L * 60;        // ...30 phut 1 lan
56	const long MIST_BOOST_EVERY_SEC = 15L * 60;  // ...hoac 15 phut 1 lan khi MIST_BOOST
57	const long MIST_START_SEC = 8L * 3600;       // Chi phun tu 8h...
58	const long MIST_END_SEC = 16L * 3600;        // ...den truoc 16h
59	// Muon test nhanh thi tam doi MIST_EVERY_SEC = 120 (phun 30 giay moi 2 phut)
60	
61	// Gia tri hieu chuan mac dinh (ban se cap nhat sau khi test thuc te)
62	int airValue = 970;   // Gia tri RAW khi cam bien o ngoai khong khi kho (0%)
63	int waterValue = 746; // Gia tri RAW khi nhung cam bien vao nuoc (100%)
64	
65	const int SAMPLE_COUNT = 10; // So lan doc de lay trung binh
66	
67	// Nguong tuoi: duoi LOW thi bat dau tuoi, tren HIGH thi dung tuoi.
68	// Khoang cach 15% de moi dot tuoi dam roi de dat kho bot, thay vi tuoi lat nhat lien tuc.
69	const int MOISTURE_LOW = 50;
70	const int MOISTURE_HIGH = 65;
71	
72	// RAW thap hon muc nay nghia la cam bien mat nguon / tuot day (nhu luc truoc doc 9-103)
73	const int SENSOR_FAULT_RAW = 600;
74	
75	// Luu luong bom do thuc te: cho bom chay 30 giay vao coc co vach, lay so ml nhan 2.
76	// Bom chim mini 3-6V da gan ong thuong duoc khoang 1 lit/phut.
77	const unsigned long PUMP_FLOW_ML_PER_MIN = 1000;
78	const unsigned long WATER_PER_PULSE_ML = 100; // Luong nuoc moi lan relay dong
79	const unsigned long PUMP_ON_MS = WATER_PER_PULSE_ML * 60000UL / PUMP_FLOW_ML_PER_MIN; // 100 ml -> 6 giay
80	
81	// Moi lan chi bom ngan roi cho nuoc ngam xuong toi cam bien, tranh bom tran chau khi cam bien phan ung cham.
82	// Muon test nhanh thi tam doi SOAK_MS = 5000UL, REST_MS = 60000UL.
83	const unsigned long SOAK_MS = 60000UL;        // Cho nuoc ngam giua 2 lan bom (60 giay)
84	const unsigned long DRY_CONFIRM_MS = 10000UL; // Phai kho lien tuc 10 giay moi bat dau tuoi, tranh 1 lan doc nhieu
85	const int MAX_PULSES = 8;                     // Toi da 8 lan bom (~800 ml) moi dot tuoi
86	const unsigned long REST_MS = 30UL * 60000;   // Bom du 8 lan ma chua du am thi nghi 30 phut cho nuoc lan deu chau
87	
88	// Khoa bom (den khi bam RESET Nano) khi bom du 8 lan ma do am tang chua toi MIN_RISE:
89	// het nuoc, tuot ong hoac bom hong. Hoac khi MAX_INCOMPLETE_CYCLES dot lien tiep khong du am, tranh ngap chau.
90	const int MIN_RISE = 5;
91	const int MAX_INCOMPLETE_CYCLES = 3;
92	
93	const unsigned long CONTROL_MS = 500; // Doc cam bien, quyet dinh tuoi / phun moi 0.5 giay
94	
95	int rawValue = 0;                   // Lan doc cam bien gan nhat
96	int moisturePercent = 0;
97	bool sensorFault = false;
98	unsigned long lastControl = 0;
99	
100	bool watering = false;              // Dang trong dot tuoi (do am chua len toi MOISTURE_HIGH)
101	bool pumpOn = false;                // May bom dang chay
102	bool pumpLocked = false;            // Bom bi khoa vi nghi het nuoc / hong bom
103	unsigned long pumpStartTime = 0;    // Thoi diem bat bom gan nhat
104	unsigned long pumpStopTime = 0;     // Thoi diem tat bom gan nhat
105	unsigned long drySince = 0;         // Thoi diem do am bat dau xuong duoi MOISTURE_LOW
106	int pulseCount = 0;                 // So lan da bom trong dot tuoi hien tai
107	int cycleStartMoisture = 0;         // Do am luc bat dau dot tuoi
108	int incompleteCycles = 0;           // So dot lien tiep bom du MAX_PULSES ma chua du am
109	bool resting = false;               // Dang nghi REST_MS sau 1 dot chua du am
110	unsigned long restStart = 0;
111	
112	bool mistOn = false;                // May phun suong dang chay
113	unsigned long mistOnSince = 0;      // millis() luc relay phun dong
114	byte mistPress = 0;                 // Bam S1 sau khi cap dien: 0 = chua bam, 1 = dang giu nut, 2 = xong
115	int mistMode = MIST_NORMAL;         // Che do phun ESP gui gan nhat ("MIST:<1-3>")
116	
117	// Gio that: ESP gui "TIME:hh:mm:ss" moi 60 giay, giua 2 lan Nano tu dem bang millis().
118	// ESP mat gio (khoi dong lai luc khong co Internet) thi Nano van tu dem tiep toi da TIME_HOLD_MS.
119	const unsigned long TIME_HOLD_MS = 12UL * 3600000; // 12 gio: dong ho Nano chi lech vai phut
120	long timeBaseSec = -1;              // Giay trong ngay luc nhan dong TIME gan nhat, -1 = chua biet gio
121	unsigned long timeBaseMs = 0;       // millis() luc nhan dong do
122	
123	// Ket qua AI moi, dang "AI:<dong la>|<dong qua>", vd "AI:La ca chua: Moc suong 97%|Qua ca chua: Tuoi 92%".
124	// Den tu ESP32-CAM (app gui len ESP, ESP chuyen xuong qua D8) hoac tu laptop (ai/service.py, cap USB).
125	// Moi dong AI: la 1 lan chup moi: LCD hien 2 dong ket qua AI_SHOW_MS roi quay ve man hinh chinh.
126	const unsigned long AI_SHOW_MS = 20000;
127	const byte AI_TEXT_LEN = 40;        // Moi dong toi da 40 ky tu (khop RESULT_MAX_LEN cua ESP32-CAM)
128	char leafText[AI_TEXT_LEN + 1] = "";
129	char fruitText[AI_TEXT_LEN + 1] = "";
130	bool showingAi = false;             // Dang hien ket qua AI thay cho man hinh chinh
131	unsigned long aiShowStart = 0;
132	
133	// Dong dai hon 16 ky tu thi chay chu: dung o dau SCROLL_HOLD_MS, moi SCROLL_STEP_MS dich 1 ky tu, dung o cuoi
134	const unsigned long SCROLL_HOLD_MS = 1500;
135	const unsigned long SCROLL_STEP_MS = 350;
136	
137	// Noi dung dang hien tren LCD: chi ghi lai dong nao doi, khong ghi lien tuc ca 2 dong
138	char shown[2][17] = {"", ""};
139	
140	// Gui do am cho ESP32-CAM de app xem duoc (ESP dua len trang /status)
141	const unsigned long SOIL_REPORT_MS = 5000;
142	unsigned long lastSoilReport = 0;
143	
144	// Bo dem cho 1 dong lenh dang nhan do. Moi cong Serial 1 bo dem rieng de 2 nguon khong tron lan nhau.
145	// Du cho dong AI dai nhat: "AI:" + 40 + "|" + 40 ky tu.
146	struct LineBuffer {
147	  char data[88];
148	  byte len;
149	};
150	LineBuffer usbLine = {"", 0};
151	LineBuffer espLine = {"", 0};
152	
153	void readSerialPorts();
154	
155	// Cho ms mili giay ma van nhan lenh tu USB va ESP. Bo dem SoftwareSerial chi 64 byte,
156	// dung delay() lau thi dong AI dai (~85 ky tu) bi tran, mat chu.
157	void waitListening(unsigned long ms) {
158	  unsigned long start = millis();
159	  do {
160	    readSerialPorts();
161	  } while (millis() - start < ms);
162	}
163	
164	// Doc A0 nhieu lan roi lay trung binh de so do on dinh hon
165	int readSoilAverage() {
166	  long sum = 0; // Dung long vi 10 x 1023 vuot qua gioi han an toan cua int
167	  for (int i = 0; i < SAMPLE_COUNT; i++) {
168	    sum += analogRead(SOIL_PIN);
169	    waitListening(10); // Nghi ngan giua cac lan doc
170	  }
171	  return sum / SAMPLE_COUNT;
172	}
173	
174	// Relay dong/ngat gay nhieu dien, LCD de bi lech du lieu va hien ky tu rac.
175	// Cho nhieu qua roi khoi tao lai LCD; updateLcd() se ve lai toan bo noi dung ngay sau do.
176	// Bom / phun dang chay van tiep tuc gay nhieu, nen trong luc do khoi tao lai LCD moi LCD_REFRESH_MS
177	// de ky tu rac tu het sau toi da vai giay (man hinh chop nhe 1 lan).
178	const unsigned long LCD_REFRESH_MS = 5000;
179	unsigned long lastLcdReset = 0;
180	
181	void resetLcdAfterRelay() {
182	  waitListening(50);
183	  lcd.begin(16, 2);
184	  shown[0][0] = '\0';
185	  shown[1][0] = '\0';
186	  lastLcdReset = millis();
187	}
188	
189	void setPump(bool on) {
190	  digitalWrite(RELAY_PIN, on ? RELAY_ACTIVE : !RELAY_ACTIVE);
191	  if (on && !pumpOn) {
192	    pumpStartTime = millis();
193	  } else if (!on && pumpOn) {
194	    pumpStopTime = millis();
195	  }
196	  if (on != pumpOn) {
197	    resetLcdAfterRelay();
198	  }
199	  pumpOn = on;
200	}
201	
202	// Bat: relay cap dien, updateMistButton() bam S1 sau MIST_BOOT_MS.
203	// Tat: ngat relay, mach phun mat dien nen lan sau lai bat dau tu TAT: Nano luon biet mach dang bat hay tat.
204	void setMist(bool on) {
205	  digitalWrite(MIST_PIN, on ? MIST_RELAY_ACTIVE : !MIST_RELAY_ACTIVE);
206	  if (on != mistOn) {
207	    mistOnSince = millis();
208	    mistPress = 0;
209	    pinMode(MIST_BTN_PIN, INPUT);  // Tat giua luc dang bam thi nha nut ngay
210	    resetLcdAfterRelay();
211	  }
212	  mistOn = on;
213	}
214	
215	// Goi lien tuc trong loop(): giu S1 dung MIST_PRESS_MS du control() co dung doc cam bien
216	void updateMistButton(unsigned long now) {
217	  if (!mistOn || mistPress == 2) {
218	    return;
219	  }
220	  if (mistPress == 0 && now - mistOnSince >= MIST_BOOT_MS) {
221	    digitalWrite(MIST_BTN_PIN, LOW);  // Dat LOW truoc khi chuyen OUTPUT de khong loe HIGH
222	    pinMode(MIST_BTN_PIN, OUTPUT);
223	    mistPress = 1;
224	  } else if (mistPress == 1 && now - mistOnSince >= MIST_BOOT_MS + MIST_PRESS_MS) {
225	    pinMode(MIST_BTN_PIN, INPUT);
226	    mistPress = 2;
227	    // Mach phun bat dau rung sieu am luc bam S1, sau lan reset LCD trong setMist(): reset lai lan nua
228	    resetLcdAfterRelay();
229	  }
230	}
231	
232	// Giay trong ngay (0-86399) luc nay, -1 neu chua biet gio
233	long secondOfDay(unsigned long now) {
234	  if (timeBaseSec < 0 || now - timeBaseMs > TIME_HOLD_MS) {
235	    return -1;
236	  }
237	  return (timeBaseSec + (long)((now - timeBaseMs) / 1000)) % 86400L;
238	}
239	
240	// Luc nay co phun khong: dung khung gio, dung nhip, va la khong bi benh nam / vi khuan
241	bool mistShouldRun(unsigned long now) {
242	  long sec = secondOfDay(now);
243	  if (sec < 0 || mistMode == MIST_STOP || sec < MIST_START_SEC || sec >= MIST_END_SEC) {
244	    return false; // Chua biet gio thi khong phun, tranh phun nham ban dem
245	  }
246	  long every = mistMode == MIST_BOOST ? MIST_BOOST_EVERY_SEC : MIST_EVERY_SEC;
247	  return sec % every < MIST_ON_SEC;
248	}
249	
250	// Chep toi da AI_TEXT_LEN ky tu
251	void copyText(char *dst, const char *src, size_t len) {
252	  len = min(len, (size_t)AI_TEXT_LEN);
253	  memcpy(dst, src, len);
254	  dst[len] = '\0';
255	}
256	
257	// Cac lenh nhan duoc (go tay tren Serial Monitor cung duoc, de thu):
258	//   AI:<dong la>|<dong qua>   ket qua moi, LCD hien AI_SHOW_MS. Tra loi "AI OK" de ESP khoi gui lai. "AI:" = thoi hien
259	//   MIST:<1-3>                che do phun suong (MIST_*)
260	//   TIME:hh:mm:ss             gio that
261	// reply: cong Serial da gui dong nay, de tra loi dung nguon
262	void handleSerialLine(const char *line, Stream &reply) {
263	  if (strncmp(line, "AI:", 3) == 0) {
264	    const char *text = line + 3;
265	    const char *bar = strchr(text, '|');
266	    copyText(leafText, text, bar ? (size_t)(bar - text) : strlen(text));
267	    copyText(fruitText, bar ? bar + 1 : "", bar ? strlen(bar + 1) : 0);
268	    showingAi = text[0] != '\0';
269	    aiShowStart = millis();
270	    reply.println("AI OK");
271	  } else if (strncmp(line, "MIST:", 5) == 0) {
272	    int mode = atoi(line + 5);
273	    if (mode >= MIST_NORMAL && mode <= MIST_BOOST) {
274	      mistMode = mode;
275	    }
276	  } else if (strncmp(line, "TIME:", 5) == 0) {
277	    int h, m, s;
278	    if (sscanf(line + 5, "%d:%d:%d", &h, &m, &s) == 3 && h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
279	      timeBaseSec = h * 3600L + m * 60L + s;
280	      timeBaseMs = millis();
281	    }
282	  }
283	}
284	
285	// Lay het ky tu dang cho trong bo dem cua 1 cong Serial, gap '\n' thi xu ly ca dong. Khong chan loop().
286	void readLines(Stream &port, LineBuffer &line) {
287	  while (port.available() > 0) {
288	    char c = port.read();
289	    if (c == '\r') {
290	      continue;
291	    }
292	    if (c == '\n') {
293	      line.data[line.len] = '\0';
294	      handleSerialLine(line.data, port);
295	      line.len = 0;
296	    } else if (line.len < sizeof(line.data) - 1) {
297	      line.data[line.len++] = c;
298	    }
299	  }
300	}
301	
302	// Nhan lenh tu laptop (cap USB) va tu ESP32-CAM (D8), neu co
303	void readSerialPorts() {
304	  readLines(Serial, usbLine);
305	  readLines(espSerial, espLine);
306	}
307	
308	// Gui 1 dong "SOIL:<do am %>,<raw>,<bom 0/1>,<loi cam bien 0/1>,<phun suong 0/1>" cho ESP32-CAM, vd "SOIL:45,812,0,0,1"
309	void reportSoil() {
310	  espSerial.print("SOIL:");
311	  espSerial.print(moisturePercent);
312	  espSerial.print(',');
313	  espSerial.print(rawValue);
314	  espSerial.print(',');
315	  espSerial.print(pumpOn ? 1 : 0);
316	  espSerial.print(',');
317	  espSerial.print(sensorFault ? 1 : 0);
318	  espSerial.print(',');
319	  espSerial.println(mistOn ? 1 : 0);
320	}
321	
322	// Doc cam bien, quyet dinh tuoi va phun suong, bao cao. Goi moi CONTROL_MS.
323	void control() {
324	  // 1. Doc gia tri Analog (0 - 1023), lay trung binh SAMPLE_COUNT lan
325	  rawValue = readSoilAverage();
326	  sensorFault = rawValue < SENSOR_FAULT_RAW;
327	
328	  // 2. Quy doi ra % do am dat (0% - 100%)
329	  // Luu y: Cam bien dien dung cang kho thi gia tri cang cao, cang uot gia tri cang thap
330	  moisturePercent = map(rawValue, airValue, waterValue, 0, 100);
331	  moisturePercent = constrain(moisturePercent, 0, 100);
332	
333	  // 3. Quyet dinh tuoi
334	  unsigned long now = millis();
335	  if (sensorFault || moisturePercent >= MOISTURE_LOW) {
336	    drySince = now; // Chua kho thi dem lai tu dau
337	  }
338	  bool restDone = !resting || now - restStart >= REST_MS;
339	
340	  if (sensorFault || pumpLocked) {
341	    // Cam bien loi thi khong tin so do, bom bi khoa thi cho nguoi kiem tra: tat bom cho an toan
342	    watering = false;
343	  } else if (watering && moisturePercent >= MOISTURE_HIGH) {
344	    watering = false; // Du am, ket thuc dot tuoi
345	    incompleteCycles = 0;
346	  } else if (!watering && restDone && now - drySince >= DRY_CONFIRM_MS) {
347	    watering = true; // Bat dau dot tuoi moi
348	    resting = false;
349	    pulseCount = 0;
350	    cycleStartMoisture = moisturePercent;
351	  }
352	
353	  if (pumpOn) {
354	    // Bom du PUMP_ON_MS hoac khong can tuoi nua thi tat
355	    if (!watering || now - pumpStartTime >= PUMP_ON_MS) {
356	      setPump(false);
357	    }
358	  } else if (watering && now - pumpStopTime >= SOAK_MS) {
359	    if (pulseCount < MAX_PULSES) {
360	      // Da cho nuoc tham du lau ma van kho thi bom them 1 lan
361	      setPump(true);
362	      pulseCount++;
363	    } else {
364	      // Bom du MAX_PULSES lan, ngam xong ma van chua du am
365	      watering = false;
366	      incompleteCycles++;
367	      if (moisturePercent - cycleStartMoisture < MIN_RISE || incompleteCycles >= MAX_INCOMPLETE_CYCLES) {
368	        pumpLocked = true;
369	      } else {
370	        resting = true;
371	        restStart = now;
372	      }
373	    }
374	  }
375	
376	  // 4. Phun suong theo gio va tinh trang la
377	  setMist(mistShouldRun(now));
378	
379	  // 5. In ra Serial Monitor (ai/service.py doc phan "Raw: ... Do am: ...% Bom: ..." de ghi CSV, dung doi)
380	  Serial.print("Raw: ");
381	  Serial.print(rawValue);
382	  Serial.print("  -->  Do am: ");
383	  Serial.print(moisturePercent);
384	  Serial.print("%  Bom: ");
385	  Serial.print(pumpOn ? "ON" : "OFF");
386	  Serial.print("  Phun: ");
387	  Serial.print(mistOn ? "ON" : "OFF");
388	  Serial.print(mistMode == MIST_STOP ? " (dung: la benh)" : mistMode == MIST_BOOST ? " (tang: nhen do)" : "");
389	  if (watering) {
390	    Serial.print("  Lan bom: ");
391	    Serial.print(pulseCount);
392	    Serial.print('/');
393	    Serial.print(MAX_PULSES);
394	  }
395	  if (secondOfDay(now) < 0) {
396	    Serial.print("  [CHUA CO GIO: khong phun]");
397	  }
398	  if (sensorFault) {
399	    Serial.print("  [LOI CAM BIEN]");
400	  }
401	  if (pumpLocked) {
402	    Serial.print("  [KHOA BOM: kiem tra nuoc, ong, bom roi bam RESET]");
403	  }
404	  Serial.println();
405	
406	  // 6. Gui do am cho ESP32-CAM moi SOIL_REPORT_MS. SoftwareSerial dang gui thi khong nhan duoc,
407	  // nen ESP dang gui do 1 dong thi doi nhan xong, khong de dong AI bi mat chu o giua
408	  if (now - lastSoilReport >= SOIL_REPORT_MS && espLine.len == 0 && espSerial.available() == 0) {
409	    lastSoilReport = now;
410	    reportSoil();
411	  }
412	}
413	
414	// Ghi 1 dong LCD: 16 ky tu cua text bat dau tu ky tu thu `from`, thieu thi them dau cach (xoa chu cu)
415	void showRow(byte row, const char *text, byte from) {
416	  char buf[17];
417	  size_t len = strlen(text);
418	  for (byte i = 0; i < 16; i++) {
419	    buf[i] = from + i < len ? text[from + i] : ' ';
420	  }
421	  buf[16] = '\0';
422	  if (strcmp(buf, shown[row]) != 0) {
423	    lcd.setCursor(0, row);
424	    lcd.print(buf);
425	    strcpy(shown[row], buf);
426	  }
427	}
428	
429	// Chay chu: dong dai hon 16 ky tu thi hien tu ky tu thu may, t = thoi gian tu luc bat dau hien
430	byte scrollFrom(const char *text, unsigned long t) {
431	  int extra = (int)strlen(text) - 16;
432	  if (extra <= 0) {
433	    return 0;
434	  }
435	  t %= 2 * SCROLL_HOLD_MS + (unsigned long)extra * SCROLL_STEP_MS;
436	  if (t < SCROLL_HOLD_MS) {
437	    return 0;
438	  }
439	  return min((t - SCROLL_HOLD_MS) / SCROLL_STEP_MS + 1, (unsigned long)extra);
440	}
441	
442	void updateLcd(unsigned long now) {
443	  if (showingAi && now - aiShowStart >= AI_SHOW_MS) {
444	    showingAi = false;
445	  }
446	
447	  if (showingAi) {
448	    // Man hinh ket qua AI: dong 1 = la, dong 2 = qua (laptop chi co model la thi khong co dong qua)
449	    unsigned long t = now - aiShowStart;
450	    const char *fruit = fruitText[0] != '\0' ? fruitText : "Khong ro qua";
451	    showRow(0, leafText, scrollFrom(leafText, t));
452	    showRow(1, fruit, scrollFrom(fruit, t));
453	    return;
454	  }
455	
456	  // Man hinh chinh. Dong 1: do am + gio (hoac bao loi cam bien), vd "Do am: 45% 14:05"
457	  char row[17];
458	  long sec = secondOfDay(now);
459	  if (sensorFault) {
460	    strcpy(row, "LOI CAM BIEN DAT");
461	  } else if (sec < 0) {
462	    snprintf(row, sizeof(row), "Do am:%3d%% --:--", moisturePercent);
463	  } else {
464	    snprintf(row, sizeof(row), "Do am:%3d%% %02d:%02d", moisturePercent, (int)(sec / 3600), (int)(sec / 60 % 60));
465	  }
466	  showRow(0, row, 0);
467	
468	  // Dong 2: bom + phun suong, vd "Bom:CHO Phun:OFF". CHO = dang trong dot tuoi, doi nuoc ngam; LOI = bom bi khoa
469	  snprintf(row, sizeof(row), "Bom:%s Phun:%s",
470	           pumpLocked ? "LOI" : pumpOn ? "ON " : watering ? "CHO" : "OFF", mistOn ? "ON " : "OFF");
471	  showRow(1, row, 0);
472	}
473	
474	void setup() {
475	  Serial.begin(9600);
476	  espSerial.begin(9600);
477	
478	  // Tat bom va phun suong truoc roi moi dat OUTPUT, de relay khong bi dong thoang qua luc khoi dong
479	  digitalWrite(RELAY_PIN, !RELAY_ACTIVE);
480	  pinMode(RELAY_PIN, OUTPUT);
481	  digitalWrite(MIST_PIN, !MIST_RELAY_ACTIVE);
482	  pinMode(MIST_PIN, OUTPUT);
483	  digitalWrite(MIST_BTN_PIN, LOW);  // INPUT khong pull-up: tha noi, khong bam S1
484	  pinMode(MIST_BTN_PIN, INPUT);
485	
486	  lcd.begin(16, 2);
487	  lcd.clear();
488	
489	  // Man hinh chao khoi dong
490	  lcd.setCursor(0, 0);
491	  lcd.print("He Thong Tuoi");
492	  lcd.setCursor(0, 1);
493	  lcd.print("Do Am Dat v2.0");
494	  delay(1500);
495	  lcd.clear();
496	}
497	
498	void loop() {
499	  readSerialPorts();
500	  if (lastControl == 0 || millis() - lastControl >= CONTROL_MS) {
501	    lastControl = millis();
502	    control();
503	  }
504	  updateMistButton(millis());
505	  // lcd.begin() chan ~60 ms: chi lam khi ESP khong dang gui do 1 dong, giong reportSoil()
506	  if ((pumpOn || mistOn) && millis() - lastLcdReset >= LCD_REFRESH_MS && espLine.len == 0 &&
507	      espSerial.available() == 0) {
508	    resetLcdAfterRelay();
509	  }
510	  updateLcd(millis());
511	}
512	----
513	# Sơ đồ nối dây – Hệ thống tưới cây TT
514	
515	Hệ thống gồm Arduino Nano (tưới cây, LCD, 2 relay) và ESP32-CAM (chụp ảnh, nhận kết quả AI từ app). Hai bo nói chuyện với nhau qua 2 dây UART đi qua module BSS138: ESP chạy 3,3 V còn Nano chạy 5 V.
516	
517	Bản này khớp với firmware [`src/main.cpp`](../src/main.cpp) (Nano) và [`esp32cam/src/main.cpp`](../esp32cam/src/main.cpp), kiểm tra ngày 17/10/2026. Đổi chân trong code thì sửa cả file này.
518	
519	## 1. Chân Arduino Nano
520	
521	| Chân Nano | Nối tới | Ghi chú |
522	|---|---|---|
523	| D12, D11, D5, D4, D3, D2 | LCD 1602: RS, E, D4, D5, D6, D7 | `LiquidCrystal lcd(12, 11, 5, 4, 3, 2)` |
524	| A0 | Cảm biến độ ẩm đất (AOUT) | Cảm biến điện dung |
525	| D7 | Relay bơm (IN1) | `RELAY_PIN` |
526	| D6 | Relay máy phun sương (IN2 nếu dùng module 2 kênh) | `MIST_PIN` |
527	| D10 | Diode 1N4007 → chân tín hiệu nút S1 của mạch phun | `MIST_BTN_PIN`, vạch diode quay về phía Nano |
528	| D8 (RX) | BSS138 HV2 | Nhận từ ESP IO13 |
529	| D9 (TX) | BSS138 HV1 | Gửi sang ESP IO14 |
530	| 5V | Ray 5V của Nano | Khoảng 4,7 V sau diode 1N5819 |
531	| GND | GND chung | |
532	
533	Cả 2 relay đều **kích mức LOW** (`RELAY_ACTIVE` và `MIST_RELAY_ACTIVE` đều là `LOW`). Nếu relay của bạn kích mức HIGH thì đổi 2 hằng này thành `HIGH`.
534	
535	## 2. Chân ESP32-CAM (AI-Thinker)
536	
537	| Chân ESP32-CAM | Nối tới | Ghi chú |
538	|---|---|---|
539	| 5V | Ray 5V-ADP (adapter chung) | Cắm tụ 470–1000 µF sát chân này, chân (+) vào 5V |
540	| GND (cạnh chân 5V) | GND chung | |
541	| 3V3 | BSS138 LV | Chỉ làm mức áp tham chiếu cho phía 3,3 V, không dùng để nuôi module khác |
542	| IO14 (RX) | BSS138 LV1 | Nhận dữ liệu từ Nano D9 |
543	| IO13 (TX) | BSS138 LV2 | Gửi dữ liệu tới Nano D8 |
544	| VCC | Để trống | Đây là ngõ ra, không phải chỗ cấp nguồn |
545	| IO4 | Để trống | Đã nối sẵn với đèn flash trên bo |
546	| IO0, U0R, U0T | Để trống | Chỉ dùng lúc nạp code |
547	
548	Camera OV2640 cắm bằng cáp dẹt có sẵn trên bo, không phải nối dây. **Không cắm thẻ microSD**, vì IO13 và IO14 cũng là chân dữ liệu của khe thẻ.
549	
550	## 3. Module BSS138 (4 kênh)
551	
552	| Chân BSS138 | Nối tới | Ghi chú |
553	|---|---|---|
554	| HV | Ray 5V của Nano | Khoảng 4,7 V sau diode |
555	| LV | ESP32-CAM 3V3 | Khoảng 3,3 V |
556	| GND | GND chung | Module có 2 chân GND (mỗi bên 1 chân) thì nối cả hai |
557	| HV1 | Nano D9 (TX) | Chiều Nano → ESP |
558	| LV1 | ESP32-CAM IO14 (RX) | |
559	| HV2 | Nano D8 (RX) | Chiều ESP → Nano |
560	| LV2 | ESP32-CAM IO13 (TX) | |
561	| HV3, HV4, LV3, LV4 | Để trống | |
562	
563	Không đảo HV với LV. Khi chưa truyền dữ liệu, HV1 và HV2 đo khoảng 4,7 V, còn LV1 và LV2 đo khoảng 3,3 V.
564	
565	## 4. Relay bơm và relay phun sương
566	
567	Phía điều khiển (dùng module relay 2 kênh, hoặc 2 module 1 kênh):
568	
569	| Chân relay | Nối tới |
570	|---|---|
571	| VCC | Ray 5V của Nano |
572	| GND | GND chung |
573	| IN1 | Nano D7 (bơm) |
574	| IN2 | Nano D6 (phun sương) |
575	
576	### Mạch bơm (phía tải của relay 1)
577	
578	| Từ | Đến | Ghi chú |
579	|---|---|---|
580	| (+) nguồn bơm, qua jack DC | Relay 1 COM | Dây đỏ |
581	| Relay 1 NO | (+) bơm | Dùng NO để bơm tắt khi Nano mất nguồn |
582	| (−) bơm | (−) nguồn bơm | Dây đen |
583	| Diode 1N4007 | Hai cực bơm | Vạch (cathode) quay về (+) bơm. Lắp ngược sẽ chập nguồn bơm khi relay đóng |
584	| Tụ gốm 100 nF (mã 104) | Hai cực bơm | Không phân cực, hàn sát thân bơm để giảm nhiễu làm LCD ra ký tự rác |
585	
586	Chân NC của relay để trống. Không lấy nguồn bơm từ chân 5V của Nano: dòng khởi động của bơm làm sụt áp, khiến Nano bị reset và LCD ra ký tự rác.
587	
588	### Mạch máy phun sương mini 5V (phía tải của relay 2)
589	
590	| Từ | Đến | Ghi chú |
591	|---|---|---|
592	| Ray 5V-ADP (+) | Relay 2 COM | |
593	| Relay 2 NO | (+) của module phun sương | Phun sương tắt khi Nano mất nguồn |
594	| (−) của module phun sương | GND chung | |
595	| Chân tín hiệu nút S1 (đầu không vạch của 1N4007) | Nano D10 (đầu có vạch) | Chỉ cần với mạch có nút bấm, xem bên dưới |
596	
597	- Module phun sương có mạch điện tử riêng nên không cần diode như quạt hay bơm.
598	- **Thử trước khi lắp:** cắm module thẳng vào 5V xem nó có **tự phun ngay khi có điện** không.
599	- **Mạch có nút bấm JY-M36A0** (2–4 tấm phim, cổng Type-C): có điện vẫn TẮT, phải bấm S1 mới phun (S2 là chế độ phun lần lượt J1→J4, không dùng). Hàn đầu không vạch của 1N4007 vào chân tín hiệu của S1: chân đo được khoảng 5 V so với GND lúc thả nút, 2 chân còn lại là GND. Mỗi lần phun, firmware đóng relay 2, đợi 0,5 giây rồi kéo D10 xuống 0,2 giây (giống bấm S1), hết giờ thì ngắt relay để mạch về TẮT. Thử tay trước khi cắm vào Nano: chạm đầu có vạch vào GND nửa giây thì mạch phải bật.
600	- 2 tấm phim kéo khoảng 0,7 A. Đi dây riêng từ cọc ra của bộ hạ áp tới relay, không qua ray breadboard, để ESP32-CAM không bị sụt áp.
601	- Module lấy điện từ ray 5V-ADP, nên khi chỉ cắm USB laptop thì relay 2 vẫn kêu tách nhưng không phun. Đừng để module chạy khi cốc hết nước.
602	
603	**Khi nào phun** (firmware tự làm, cần biết giờ thật từ ESP32-CAM hoặc laptop):
604	
605	| Điều kiện | Phun sương |
606	|---|---|
607	| Lá khỏe (hoặc chưa có kết quả AI), 8h–16h | 30 giây, 30 phút 1 lần (đúng :00 và :30) |
608	| Sau 16h và ban đêm | Không phun, để lá kịp khô trước tối |
609	| AI báo bệnh nấm / vi khuẩn, hoặc nghi bệnh bất kỳ | Dừng hẳn, đến khi AI báo lá khỏe lại |
610	| AI chắc chắn nhện đỏ (≥ 90%) | 30 giây, 15 phút 1 lần, vẫn chỉ 8h–16h |
611	| Virus khảm lá, xoăn vàng lá | Phun bình thường |
612	| Ảnh tối hoặc không thấy lá | Giữ nguyên chế độ đang chạy |
613	| Chưa biết giờ | Không phun |
614	
615	Đổi thời gian ở các hằng `MIST_*` trong `src/main.cpp`.
616	
617	## 5. Nguồn điện
618	
619	Mạch dùng 3 nguồn. GND của USB, adapter, Nano, ESP32-CAM, BSS138 và máy phun sương nối chung với nhau, riêng nguồn bơm thì không.
620	
621	| Nguồn | Cấp cho | Nối vào GND chung? |
622	|---|---|---|
623	| USB laptop → cổng USB của Nano | Nano khi nạp code, và Serial 9600 tới laptop | Có, qua cáp USB |
624	| Adapter 5V 2A → ray 5V-ADP | Chân 5V của ESP32-CAM, chân 5V của Nano qua diode 1N5819, và máy phun sương qua COM–NO của relay 2 | Có. Bắt buộc phải nối thì UART mới chạy |
625	| Adapter hoặc pin 5V riêng cho bơm | Bơm, đi qua COM–NO của relay 1 | Không, relay đã cách ly hai phía |
626	
627	- **Diode 1N5819:** đầu không có vạch cắm vào ray 5V-ADP, đầu có vạch cắm vào ray 5V của Nano. Diode chặn USB và adapter đẩy dòng ngược vào nhau, nên cắm cả hai cùng lúc vẫn an toàn.
628	- **Ray 5V của Nano** (khoảng 4,7 V sau diode) nuôi LCD, biến trở, cảm biến, cuộn hút của 2 relay và chân HV của BSS138.
629	- **Tụ 470–1000 µF** nằm giữa 5V và GND, sát chân ESP32-CAM: chân dài (+) vào 5V, phía có vạch (−) vào GND.
630	- **Dòng trên adapter** khoảng 0,9 A: ESP32-CAM khoảng 0,25 A (hơn khi bật flash), ray Nano khoảng 0,2 A, máy phun sương mini thường 0,3–0,5 A (đo lại module của bạn). Adapter 2 A đủ. Diode 1N5819 chịu 1 A, chỉ phải gánh phần ray Nano.
631	- **Đổi nguồn từ USB sang adapter có thể làm giá trị Raw của cảm biến lệch đi.** Ghi lại Raw lúc khô và lúc nhúng nước, rồi sửa `airValue` và `waterValue` trong `src/main.cpp` nếu cần.
632	
633	## 6. Nạp code
634	
635	Nano: cắm cáp USB, chạy `pio run -t upload` ở thư mục gốc `heThongTuoiCayTT`.
636	
637	ESP32-CAM có 2 cách nạp:
638	
639	**Qua WiFi (OTA, mặc định):** chạy `pio run -d esp32cam -t upload`, không cần tháo ESP khỏi mạch. Chạy `./esp32cam/watch_upload.sh` thì cứ lưu file code là tự build và nạp. Mật khẩu OTA nằm trong `esp32cam/secrets.ini` (copy từ `secrets.example.ini`). Cách này chỉ dùng được khi ESP đang online và đang chạy firmware có OTA.
640	
641	**Qua cáp:** chạy `pio run -d esp32cam -e esp32cam -t upload`. Lần đầu bật OTA bắt buộc phải nạp cách này, vì phải ghi lại bảng phân vùng flash. Nếu code mới làm ESP treo trước khi vào được WiFi thì cũng phải nạp lại qua cáp. Có 2 cách nối:
642	
643	- **Đế ESP32-CAM-MB:** rút ESP ra khỏi dây dupont, cắm lên đế rồi cắm USB. Nếu báo lỗi `Failed to connect`, giữ nút IO0 trên đế, bấm RST, rồi nạp lại.
644	- **Mạch USB-TTL (gạt sang 5V):** rút adapter trước, để ESP chỉ lấy nguồn từ USB-TTL. Nối như sau:
645	
646	| USB-TTL | ESP32-CAM |
647	|---|---|
648	| 5V | 5V |
649	| GND | GND |
650	| TX | U0R (IO3) |
651	| RX | U0T (IO1) |
652	| GND | IO0, chỉ nối trong lúc nạp. Nạp xong thì rút dây này rồi bấm RST |
653	
654	## 7. Dữ liệu trên 2 dây UART
655	
656	Cả 2 bên chạy 9600 baud, 8N1:
657	- Nano: `SoftwareSerial espSerial(8, 9)`.
658	- ESP: `Serial2.begin(9600, SERIAL_8N1, 14, 13)`.
659	
660	| Chiều | Dòng gửi | Khi nào |
661	|---|---|---|
662	| ESP → Nano | `MIST:<1-3>`: chế độ phun sương (1 bình thường, 2 dừng, 3 phun tăng) | Lúc ESP khởi động, mỗi 60 giây, và trước mỗi dòng `AI:` |
663	| ESP → Nano | `TIME:hh:mm:ss`, vd `TIME:14:05:37` | Như dòng `MIST`, nhưng chỉ khi ESP đã biết giờ (qua Internet, hoặc lấy từ app) |
664	| ESP → Nano | `AI:<dòng lá>\|<dòng quả>`, mỗi dòng tối đa 40 ký tự, vd `AI:La ca chua: Moc suong 97%\|Qua ca chua: Tuoi 92%` | Chỉ khi app gửi kết quả mới (`POST /result`). Nano hiện 20 giây. Không có `AI OK` sau 2 giây thì ESP gửi lại, tối đa 3 lần |
665	| Nano → ESP | `AI OK` | Trả lời mỗi dòng `AI:` |
666	| Nano → ESP | `SOIL:<độ ẩm %>,<raw>,<bơm 0/1>,<lỗi cảm biến 0/1>,<phun sương 0/1>` | Mỗi 5 giây; ESP đưa lên `/status` |
667	
668	Nano cũng nhận các dòng `AI:`, `MIST:`, `TIME:` qua cáp USB (từ `ai/service.py` hoặc Serial Monitor), nên vẫn chạy được khi chưa có ESP. Giữa 2 lần nhận `TIME`, Nano tự đếm giờ; mất `TIME` quá 12 giờ thì coi như không biết giờ.
669	
670	### Kiểm tra sau khi nối
671	
672	1. Cắm adapter, chưa cần app. Đo áp khi nghỉ: HV1 và HV2 khoảng 4,7 V, LV1 và LV2 khoảng 3,3 V.
673	2. **Chiều ESP → Nano:** từ laptop cùng WiFi, chạy
674	   ```bash
675	   curl -X POST -H "Content-Type: text/plain" --data-binary $'TEST 123\nDong 2 thu\n0' http://<IP>/result
676	   ```
677	   LCD phải hiện `TEST 123` / `Dong 2 thu` trong 20 giây rồi quay về `Do am: ...` / `Bom:... Phun:...`. Số `0` ở cuối giữ nguyên chế độ phun sương. Log của ESP phải in `[Nano] AI OK`.
678	3. **Chiều Nano → ESP:** mở `http://<IP>/status`. Mục `soil` phải khác `null` và `age_s` nhỏ hơn 10.
679	
680	| Hiện tượng | Kiểm tra |
681	|---|---|
682	| LCD không hiện `TEST 123` | Dây IO13 – LV2, HV2 – D8, GND chung giữa adapter và Nano |
683	| `/status` có `"soil":null`, hoặc `age_s` tăng mãi | Dây D9 – HV1, LV1 – IO14 |
684	| Cả 2 chiều đều không chạy | Chân HV/LV của BSS138 có bị đảo không, HV có 4,7 V và LV có 3,3 V không, GND chung |
685	| Màn hình chính hiện giờ `--:--` | Nano chưa nhận được dòng `TIME` (nên không phun sương). Xem `/status`: `"time":null` là ESP chưa biết giờ (chưa vào được WiFi có Internet, app chưa gửi kết quả nào). ESP có giờ mà LCD vẫn `--:--` thì kiểm tra dây IO13 – LV2, HV2 – D8 |
686	| ESP in `Nano khong tra loi "AI OK"` | Dây IO13 – LV2, HV2 – D8, hoặc Nano còn chạy firmware cũ |
687

