import json,glob,os
d=json.load(open('diagram.json',encoding='utf-8'))
schema=json.load(open(glob.glob(os.path.expanduser('~/.vscode/extensions/wokwi.wokwi-vscode-4.1.0*/schemas/diagram.schema.json'))[0],encoding='utf-8'))
ids={p['id'] for p in d['parts']}
pins={'wokwi-arduino-nano':{'12','11','10','9','8','7','6','5','4','3','2','0','1','13','A0','A1','A2','A3','A4','A5','A6','A7','AREF','3.3V','5V','VIN','RESET','GND.1','GND.2','RESET.2','12.2','5V.2','13.2','11.2','RESET.3','GND.3'},
'wokwi-lcd1602':{'VSS','VDD','V0','RS','RW','E','D0','D1','D2','D3','D4','D5','D6','D7','A','K'},
'wokwi-slide-potentiometer':{'VCC','SIG','GND'},'wokwi-resistor':{'1','2'},'wokwi-led':{'A','C'}}
types={p['id']:p['type'] for p in d['parts']}
bad=[]
for c in d['connections']:
  for end in c[:2]:
    pid,pin=end.split(':',1)
    if pid not in ids or pin not in pins[types[pid]]: bad.append(end)
missing=[k for k in schema['required'] if k not in d]
allowed=set(schema['properties']['parts']['items']['properties'])
extra=[(p['id'],k) for p in d['parts'] for k in p if k not in allowed]
print('connections:',len(d['connections']),'bad pins:',bad,'missing keys:',missing,'extra part keys:',extra)
"

