204	// Chi giu ky tu ASCII in duoc (LCD khong co dau tieng Viet). Bo " va \ de /status van la JSON hop le,
205	// bo | vi Nano dung no de tach dong la / dong qua.
206	String cleanLine(String text) {
207	  text.trim();
208	  String clean;
209	  for (unsigned int i = 0; i < text.length() && clean.length() < RESULT_MAX_LEN; i++) {
210	    char c = text[i];
211	    if (c >= 32 && c < 127 && c != '"' && c != '\\' && c != '|') {
212	      clean += c;
213	    }
214	  }
215	  return clean;
216	}
