218	// App gui ket qua AI: POST /result, than dang text 4 dong "<dong la>\n<dong qua>\n<che do phun>\n<gio Unix>", vd
219	// "La ca chua: Moc suong 97%\nQua ca chua: Tuoi 92%\n2\n1760000000". Gui 1 dong (curl, app cu) van duoc.
220	void handleResult() {
221	  String body = server.arg("plain");
222	  String lines[4];
223	  int start = 0;
224	  for (int i = 0; i < 4 && start <= (int)body.length(); i++) {
225	    int end = body.indexOf('\n', start);
226	    if (end < 0) {
227	      end = body.length();
228	    }
229	    lines[i] = body.substring(start, end);
230	    start = end + 1;
231	  }
232	  String leaf = cleanLine(lines[0]);
233	  String fruit = cleanLine(lines[1]);
234	  if (leaf.length() == 0 && fruit.length() == 0) {
235	    server.send(400, "text/plain", "Thieu ket qua: can it nhat 1 dong chu (nho -H \"Content-Type: text/plain\")");
236	    return;
237	  }
238	  leafLine = leaf;
239	  fruitLine = fruit;
240	  prefs.putString("leaf", leafLine);
241	  prefs.putString("fruit", fruitLine);
242	
243	  // 0 hoac khong co (app khong xem duoc la: anh toi, khong thay la) thi giu che do phun cu
244	  int mode = lines[2].toInt();
245	  if (mode >= MIST_NORMAL && mode <= MIST_BOOST && mode != mistMode) {
246	    mistMode = mode;
247	    prefs.putInt("mist", mistMode);
248	  }
249	  // Chua lay duoc gio qua Internet (vd chi phat WiFi TuoiCay-CAM) thi lay gio dien thoai
250	  long long phoneTime = atoll(lines[3].c_str());
251	  if (time(nullptr) < MIN_VALID_TIME && phoneTime > MIN_VALID_TIME) {
252	    struct timeval tv = {(time_t)phoneTime, 0};
253	    settimeofday(&tv, nullptr);
254	    Serial.println("Da lay gio tu dien thoai");
255	  }
256	
257	  // Gui che do phun + gio truoc dong AI: Nano tra loi "AI OK" ngay sau dong AI, luc do Nano khong nhan duoc gi
258	  syncNano();
259	  aiTries = 0;
260	  aiPending = true;
261	  sendAiToNano();
262	  Serial.printf("Ket qua AI moi: \"%s\" | \"%s\", phun che do %d -> da gui xuong Nano\n", leafLine.c_str(),
263	                fruitLine.c_str(), mistMode);
264	  server.send(200, "text/plain", "OK");
265	}
