351	bool isBadAp(const uint8_t *bssid) {
352	  for (const BadAp &ap : badAps) {
353	    if (ap.since > 0 && millis() - ap.since < WIFI_BAD_AP_MS && memcmp(ap.bssid, bssid, 6) == 0) {
354	      return true;
355	    }
356	  }
357	  return false;
358	}
