394	// Chay 2 mang cung luc: vao WiFi nha (router cap IP) va tu phat TuoiCay-CAM (IP co dinh 192.168.4.1).
395	// Web server tra loi tren ca 2 dia chi. ESP chi co 1 radio nen TuoiCay-CAM luon phat cung kenh voi router.
396	// Khong cho trong setup(): TuoiCay-CAM dung duoc ngay ca khi khong co router, checkWifi() in IP khi vao duoc.
397	void startWifi() {
398	  WiFi.mode(WIFI_AP_STA);
399	  WiFi.setHostname(HOSTNAME);
400	  WiFi.setSleep(false); // Tat tiet kiem dien WiFi de tra anh nhanh, on dinh hon
401	  // Tu ket noi lai trong checkWifi(): thu vien tu ket noi lai thi do tim router lien tuc, song TuoiCay-CAM chap chon
402	  WiFi.setAutoReconnect(false);
403	  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t) { staAssocTime = millis(); }, ARDUINO_EVENT_WIFI_STA_CONNECTED);
404	  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t) { staAssocTime = 0; }, ARDUINO_EVENT_WIFI_STA_GOT_IP);
405	  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t info) {
406	    staAssocTime = 0;
407	    // Bo qua ASSOC_LEAVE: do chinh checkWifi() goi WiFi.disconnect() truoc moi lan thu lai
408	    if (info.wifi_sta_disconnected.reason != WIFI_REASON_ASSOC_LEAVE) {
409	      wifiFailReason = info.wifi_sta_disconnected.reason;
410	    }
411	  }, ARDUINO_EVENT_WIFI_STA_DISCONNECTED);
412	  if (WiFi.softAP(AP_SSID, AP_PASSWORD)) {
413	    Serial.printf("Phat WiFi \"%s\"  ->  http://%s/capture\n", AP_SSID, WiFi.softAPIP().toString().c_str());
414	  } else {
415	    Serial.println("Khong phat duoc WiFi rieng TuoiCay-CAM");
416	  }
417	  beginWifi();
418	  lastWifiRetry = millis();
419	}
420	
421	// Goi moi giay trong loop(): in IP khi vua vao WiFi nha, mat thi tu thu lai
422	void checkWifi(unsigned long now) {
423	  if (WiFi.status() == WL_CONNECTED) {
424	    if (!staConnected) {
425	      staConnected = true;
426	      Serial.printf("Da ket noi \"%s\". IP: %s  ->  http://%s.local/capture\n", WIFI_SSID,
427	                    WiFi.localIP().toString().c_str(), HOSTNAME);
428	      configTzTime(TZ_VN, "pool.ntp.org", "time.google.com");  // Lay gio qua Internet, tu chinh lai moi gio
429	    }
430	    lastWifiOk = now;
431	    return;
432	  }
433	  if (staConnected) {
434	    staConnected = false;
435	    Serial.println("Mat WiFi nha, TuoiCay-CAM van chay");
436	  }
437	  // Dang co dien thoai vao TuoiCay-CAM: khong do tim router, de song TuoiCay-CAM khong bi ngat
438	  if (WiFi.softAPgetStationNum() > 0) {
439	    return;
440	  }
441	  // Vao duoc diem phat nhung chua co IP: cho, qua WIFI_DHCP_TIMEOUT_MS thi bo diem phat do, thu diem khac ngay
442	  unsigned long assoc = staAssocTime;
443	  if (assoc > 0) {
444	    if (now - assoc >= WIFI_DHCP_TIMEOUT_MS) {
445	      Serial.printf("Diem phat %02X:%02X:%02X:%02X:%02X:%02X khong cap IP, bo qua %lu phut\n", tryingBssid[0],
446	                    tryingBssid[1], tryingBssid[2], tryingBssid[3], tryingBssid[4], tryingBssid[5],
447	                    WIFI_BAD_AP_MS / 60000);
448	      markBadAp(tryingBssid);
449	      WiFi.disconnect();
450	      lastWifiRetry = now;
451	      beginWifi();
452	    }
453	    return;
454	  }
455	  unsigned long lost = now - lastWifiOk;
456	  if (lost >= WIFI_RESTART_MS) {
457	    Serial.println("Mat WiFi nha qua lau, khoi dong lai ESP32...");
458	    ESP.restart();
459	  }
460	  if (now - lastWifiRetry >= (lost >= WIFI_SLOW_AFTER_MS ? WIFI_SLOW_RETRY_MS : WIFI_RETRY_MS)) {
461	    lastWifiRetry = now;
462	    if (wifiFailReason != 0) {
463	      Serial.printf("Chua vao duoc WiFi nha (ma %u: %s)\n", wifiFailReason, wifiFailText(wifiFailReason));
464	      wifiFailReason = 0;
465	    }
466	    WiFi.disconnect();
467	    beginWifi();
468	  }
469	}
