471	void setup() {
472	  Serial.begin(115200);
473	  Serial.println("\nESP32-CAM khoi dong");
474	  pinMode(FLASH_LED_PIN, OUTPUT);
475	  digitalWrite(FLASH_LED_PIN, LOW);
476	
477	  Serial2.begin(9600, SERIAL_8N1, NANO_RX_PIN, NANO_TX_PIN);
478	  prefs.begin("ai", false);
479	  if (prefs.isKey("result")) {
480	    prefs.remove("result");  // Ket qua dang cu (1 dong 16 ky tu), khong dung nua
481	  }
482	  // Kiem tra isKey truoc: doc khoa chua co thi thu vien in loi "NOT_FOUND" moi lan khoi dong
483	  leafLine = prefs.isKey("leaf") ? prefs.getString("leaf") : "";
484	  fruitLine = prefs.isKey("fruit") ? prefs.getString("fruit") : "";
485	  mistMode = prefs.getInt("mist", MIST_NORMAL);  // Che do phun truoc khi mat dien, loop() gui lai cho Nano
486	  // Dat mui gio ngay tu dau: gio lay tu dien thoai (khi khong co Internet) cung can mui gio de doi ra gio VN
487	  setenv("TZ", TZ_VN, 1);
488	  tzset();
489	
490	  if (!initCamera()) {
491	    Serial.println("Kiem tra cap camera, nguon 5V >= 2A. Khoi dong lai sau 5 giay...");
492	    delay(5000);
493	    ESP.restart();
494	  }
495	
496	  startWifi();
497	  lastWifiOk = millis();
498	  if (MDNS.begin(HOSTNAME)) {
499	    MDNS.addService("http", "tcp", 80);
500	  }
501	
502	  // Nap code qua WiFi (OTA), laptop chay: pio run -d esp32cam -t upload
503	  // mDNS da bat o tren nen tat phan mDNS cua ArduinoOTA
504	  ArduinoOTA.setHostname(HOSTNAME);
505	  ArduinoOTA.setPassword(OTA_PASSWORD);
506	  ArduinoOTA.setMdnsEnabled(false);
507	  ArduinoOTA.onStart([]() { Serial.println("Dang nhan code moi qua WiFi..."); });
508	  ArduinoOTA.onEnd([]() { Serial.println("Nap xong, khoi dong lai"); });
509	  ArduinoOTA.onError([](ota_error_t err) { Serial.printf("Nap qua WiFi loi %u\n", err); });
510	  ArduinoOTA.begin();
511	
512	  server.on("/", handleRoot);
513	  server.on("/capture", handleCapture);
514	  server.on("/status", handleStatus);
515	  server.on("/result", HTTP_POST, handleResult);
516	  server.begin();
517	}
518	
519	void loop() {
520	  ArduinoOTA.handle();
521	  server.handleClient();
522	  readNano();
523	
524	  unsigned long now = millis();
525	  // Che do phun + gio: luc moi khoi dong, moi 60 giay, va ngay khi vua lay duoc gio
526	  if (lastNanoSync == 0 || now - lastNanoSync >= NANO_SYNC_MS || (!timeSentToNano && time(nullptr) > MIN_VALID_TIME)) {
527	    syncNano();
528	  }
529	  if (aiPending && now - aiLastTry >= AI_RETRY_MS) {
530	    if (aiTries < AI_MAX_TRIES) {
531	      sendAiToNano();
532	    } else {
533	      aiPending = false;
534	      Serial.println("Nano khong tra loi \"AI OK\": kiem tra day IO13 - LV2, HV2 - D8, hoac Nano chay code cu");
535	    }
536	  }
537	
538	  if (now - lastWifiCheck >= WIFI_CHECK_MS) {
539	    lastWifiCheck = now;
540	    checkWifi(now);
541	  }
542	  delay(2);
543	}
