275	      soilFault = fault == 1;
276	      soilMist = mist == 1;
277	      soilTime = millis();
278	    }
279	  } else if (line.length() > 0) {
280	    if (line.startsWith("AI OK")) {
281	      aiPending = false;  // Nano da nhan ket qua moi
282	    }
283	    Serial.printf("[Nano] %s\n", line.c_str());
284	  }
285	}
