360	void markBadAp(const uint8_t *bssid) {
361	  memcpy(badAps[nextBadAp].bssid, bssid, 6);
362	  badAps[nextBadAp].since = millis();
363	  nextBadAp = (nextBadAp + 1) % MAX_BAD_APS;
364	}
