366	// Quet cac diem phat ten WIFI_SSID, vao diem manh nhat chua bi danh dau hong (quet mat khoang 2-3 giay)
367	void beginWifi() {
368	  int n = WiFi.scanNetworks();
369	  int best = -1;
370	  bool skipped = false;
371	  for (int i = 0; i < n; i++) {
372	    if (WiFi.SSID(i) != WIFI_SSID) {
373	      continue;
374	    }
375	    if (isBadAp(WiFi.BSSID(i))) {
376	      skipped = true;
377	    } else if (best < 0 || WiFi.RSSI(i) > WiFi.RSSI(best)) {
378	      best = i;
379	    }
380	  }
381	  if (best >= 0) {
382	    memcpy(tryingBssid, WiFi.BSSID(best), 6);
383	    Serial.printf("Dang ket noi WiFi \"%s\" qua %s (kenh %d, %d dBm)...\n", WIFI_SSID, WiFi.BSSIDstr(best).c_str(),
384	                  WiFi.channel(best), WiFi.RSSI(best));
385	    WiFi.begin(WIFI_SSID, WIFI_PASSWORD, WiFi.channel(best), WiFi.BSSID(best));
386	  } else if (skipped) {
387	    Serial.printf("Chi thay diem phat \"%s\" khong cap IP (bo kich song?). Thu lai sau\n", WIFI_SSID);
388	  } else {
389	    Serial.printf("Khong thay WiFi \"%s\" (sai ten, WiFi 5 GHz, hoac o xa router?). Thu lai sau\n", WIFI_SSID);
390	  }
391	  WiFi.scanDelete();
392	}
