394	// Chay 2 mang cung luc: vao WiFi nha (router cap IP) va tu phat TuoiCay-CAM (IP co dinh 192.168.4.1).
395	// Web server tra loi tren ca 2 dia chi. ESP chi co 1 radio nen TuoiCay-CAM luon phat cung kenh voi router.
396	// Khong cho trong setup(): TuoiCay-CAM dung duoc ngay ca khi khong co router, checkWifi() in IP khi vao duoc.
397	void startWifi() {
398	  WiFi.mode(WIFI_AP_STA);
399	  WiFi.setHostname(HOSTNAME);
400	  WiFi.setSleep(false); // Tat tiet kiem dien WiFi de tra anh nhanh, on dinh hon
401	  // Tu ket noi lai trong checkWifi(): thu vien tu ket noi lai thi do tim router lien tuc, song TuoiCay-CAM chap chon
402	  WiFi.setAutoReconnect(false);
403	  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t) { staAssocTime = millis(); }, ARDUINO_EVENT_WIFI_STA_CONNECTED);
404	  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t) { staAssocTime = 0; }, ARDUINO_EVENT_WIFI_STA_GOT_IP);
405	  WiFi.onEvent([](WiFiEvent_t, WiFiEventInfo_t info) {
406	    staAssocTime = 0;
407	    // Bo qua ASSOC_LEAVE: do chinh checkWifi() goi WiFi.disconnect() truoc moi lan thu lai
408	    if (info.wifi_sta_disconnected.reason != WIFI_REASON_ASSOC_LEAVE) {
409	      wifiFailReason = info.wifi_sta_disconnected.reason;
410	    }
411	  }, ARDUINO_EVENT_WIFI_STA_DISCONNECTED);
412	  if (WiFi.softAP(AP_SSID, AP_PASSWORD)) {
413	    Serial.printf("Phat WiFi \"%s\"  ->  http://%s/capture\n", AP_SSID, WiFi.softAPIP().toString().c_str());
414	  } else {
415	    Serial.println("Khong phat duoc WiFi rieng TuoiCay-CAM");
416	  }
417	  beginWifi();
418	  lastWifiRetry = millis();
419	}
