421	// Goi moi giay trong loop(): in IP khi vua vao WiFi nha, mat thi tu thu lai
422	void checkWifi(unsigned long now) {
423	  if (WiFi.status() == WL_CONNECTED) {
424	    if (!staConnected) {
425	      staConnected = true;
426	      Serial.printf("Da ket noi \"%s\". IP: %s  ->  http://%s.local/capture\n", WIFI_SSID,
427	                    WiFi.localIP().toString().c_str(), HOSTNAME);
428	      configTzTime(TZ_VN, "pool.ntp.org", "time.google.com");  // Lay gio qua Internet, tu chinh lai moi gio
429	    }
430	    lastWifiOk = now;
431	    return;
432	  }
433	  if (staConnected) {
