// Kiem thu lib/FarmCore tren may tinh: g++ -std=c++11 -I<FarmCore/src> test_farmcore.cpp <FarmCore.cpp>
#include <cmath>
#include <cstdio>
#include <cstdlib>

#include "FarmCore.h"

using namespace farm;

static int failures = 0;
#define CHECK(cond)                                                   \
  do {                                                                \
    if (!(cond)) {                                                    \
      std::printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);    \
      failures++;                                                     \
    }                                                                 \
  } while (0)

// Giong src/main.cpp
const IrrigationConfig CFG = {50, 65, 10000, 6000, 5000, 8, 60000, 5, 3};
const MistConfig MIST = {30, 1800, 900, 8 * 3600, 16 * 3600, 85.0f};

// Chay update() moi 500 ms tu t0 toi t1, do am co dinh. Tra ve so lan bom bat (canh len).
int run(Irrigation &irr, unsigned long &t, unsigned long until, int moisture, bool fault = false,
        bool tankEmpty = false) {
  int starts = 0;
  bool prev = irr.pumpOn();
  for (; t < until; t += 500) {
    bool on = irr.update(t, moisture, fault, tankEmpty);
    if (on && !prev) starts++;
    prev = on;
  }
  return starts;
}

void testWateringStopsWhenWet() {
  Irrigation irr(CFG);
  unsigned long t = 0;
  CHECK(run(irr, t, 9000, 40) == 0);  // Chua du 10 giay kho
  CHECK(!irr.watering());
  CHECK(run(irr, t, 10500, 40) == 1);  // Du 10 giay: bom lan 1 ngay
  CHECK(irr.pumpOn() && irr.state() == PumpState::On);
  run(irr, t, 16500, 40);  // Bom 6 giay roi tat
  CHECK(!irr.pumpOn() && irr.state() == PumpState::Soaking);
  CHECK(run(irr, t, 22000, 40) == 1);  // Ngam 5 giay, bom lan 2
  CHECK(irr.pulseCount() == 2);
  run(irr, t, 23000, 70);  // Du am: dung ngay ca khi dang bom
  CHECK(!irr.pumpOn() && !irr.watering() && irr.state() == PumpState::Off);
}

void testLockWhenNoRise() {
  Irrigation irr(CFG);
  unsigned long t = 0;
  int starts = run(irr, t, 200000, 30);  // Do am khong tang
  CHECK(starts == 8);
  CHECK(irr.locked() && irr.state() == PumpState::Locked && !irr.pumpOn());
  CHECK(run(irr, t, 300000, 30) == 0);  // Khoa thi khong bom nua
  irr.unlock();
  CHECK(!irr.locked());
  CHECK(run(irr, t, 301000, 30) == 1);  // Mo khoa: tuoi lai ngay (da kho lau)
}

void testRestThenResume() {
  Irrigation irr(CFG);
  unsigned long t = 0;
  // Bom 8 lan, do am tang 40 -> 47 (>= minRise 5) nhung chua toi 65: nghi restMs roi tuoi tiep
  run(irr, t, 10500, 40);
  run(irr, t, 100000, 47);
  CHECK(!irr.locked());
  CHECK(irr.state() == PumpState::Resting);
  CHECK(run(irr, t, 100000 + 50000, 47) == 0);  // Dang nghi 60 giay
  CHECK(run(irr, t, 100000 + 75000, 47) >= 1);  // Nghi xong: dot moi
}

void testTankEmptyAndFault() {
  Irrigation irr(CFG);
  unsigned long t = 0;
  CHECK(run(irr, t, 30000, 30, false, true) == 0);
  CHECK(irr.state() == PumpState::NoWater);
  CHECK(run(irr, t, 41000, 30, false, false) == 1);  // Do nuoc vao: tuoi lai (sau 10 giay xac nhan kho)
  run(irr, t, 42000, 30, false, true);                 // Het nuoc giua luc bom: tat ngay
  CHECK(!irr.pumpOn() && irr.state() == PumpState::NoWater);
  CHECK(run(irr, t, 60000, 0, true, false) == 0);
  CHECK(irr.state() == PumpState::SensorFault);
}

void testMist() {
  long h8 = 8 * 3600;
  CHECK(decideMist(MIST, -1, MIST_NORMAL, 60, true, false).reason == MistReason::NoClock);
  CHECK(decideMist(MIST, 7 * 3600 + 59 * 60 + 50, MIST_NORMAL, 60, true, false).reason == MistReason::OutsideHours);
  MistDecision d = decideMist(MIST, h8 + 10, MIST_NORMAL, 60, true, false);
  CHECK(d.on && d.reason == MistReason::Scheduled);
  CHECK(decideMist(MIST, h8 + 30, MIST_NORMAL, 60, true, false).reason == MistReason::Waiting);
  CHECK(decideMist(MIST, h8 + 30 * 60 + 5, MIST_NORMAL, 60, true, false).on);    // 08:30:05
  CHECK(!decideMist(MIST, h8 + 15 * 60 + 5, MIST_NORMAL, 60, true, false).on);   // 08:15 binh thuong: khong
  CHECK(decideMist(MIST, h8 + 15 * 60 + 5, MIST_BOOST, 60, true, false).on);     // 08:15 nhen do: co
  CHECK(decideMist(MIST, h8 + 10, MIST_STOP, 60, true, false).reason == MistReason::Disease);
  CHECK(decideMist(MIST, h8 + 10, MIST_NORMAL, 90, true, false).reason == MistReason::AirHumid);
  CHECK(decideMist(MIST, h8 + 10, MIST_NORMAL, NAN, false, false).on);  // DHT loi: bo qua dieu kien do am
  CHECK(decideMist(MIST, h8 + 10, MIST_NORMAL, 60, true, true).reason == MistReason::NoWater);
  CHECK(decideMist(MIST, 16 * 3600, MIST_NORMAL, 60, true, false).reason == MistReason::OutsideHours);
}

void testConversions() {
  CHECK(percentFromRaw(400, 400, 4000) == 0);
  CHECK(percentFromRaw(4000, 400, 4000) == 100);
  CHECK(percentFromRaw(2200, 400, 4000) == 50);
  CHECK(percentFromRaw(100, 400, 4000) == 0);
  CHECK(percentFromRaw(970, 970, 746) == 0);  // Chieu nguoc (cam bien dien dung that)
  CHECK(tankLevelPercent(100, 100, 10) == 0);
  CHECK(tankLevelPercent(10, 100, 10) == 100);
  CHECK(tankLevelPercent(30, 100, 10) == 78);
  CHECK(tankLevelPercent(400, 100, 10) == 0);
  // 500 lux -> LDR ~3.24 kOhm -> AO ~0.807 V -> ADC ~1001 (VCC 3.3 V, 10 kOhm noi tiep)
  float lux = luxFromAdc(1001, 4095, 3.3f, 10000, 50, 0.7f);
  std::printf("lux(1001) = %.1f\n", lux);
